import fs from 'node:fs';
import path from 'node:path';
const backup='docs/full-text-revision-20261002/before';
fs.mkdirSync(backup,{recursive:true});
for(const dir of ['src/content/whitepaper','src/content/whitepaper-tc','src/components/whitepaper']){
 const dest=path.join(backup,dir);if(!fs.existsSync(dest)){fs.mkdirSync(path.dirname(dest),{recursive:true});fs.cpSync(dir,dest,{recursive:true});}
}
export const root=l=>`src/content/${l==='tc'?'whitepaper-tc':'whitepaper'}`;
export const p=s=>`<p>${s}</p>`;
export const h=(id,s)=>`<h2 id="${id}">${s}</h2>`;
export const ul=rows=>`<ul>${rows.map(s=>`<li>${s}</li>`).join('')}</ul>`;
export const table=(heads,rows)=>`<div class="table-wrap" tabindex="0" role="region" aria-label="${heads[0]}"><table><thead><tr>${heads.map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
export const code=s=>`<pre><code>${s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')}</code></pre>`;
export const link=(l,r,label)=>`<a href="${l==='tc'?'/tc':''}${r}">${label}</a>`;
export const img=name=>`<p><img src="/sites/web3-magne-ai-9982170f/shared/full-site/${name}" alt="MAGNE" loading="lazy"></p>`;
export function write(l,r,html){
 const file=`${root(l)}${r}.html`;const old=fs.readFileSync(file,'utf8');
 // Preserve existing incoming anchors when a chapter is reorganised.
 const ids=[...old.matchAll(/\bid="([^"]+)"/g)].map(m=>m[1]);
 const aliases=ids.filter(id=>!html.includes(`id="${id}"`));
 if(aliases.length)html=html.replace('</h1>','</h1>'+aliases.map(id=>`<span id="${id}" class="wp-legacy-anchor" aria-hidden="true"></span>`).join(''));
 fs.writeFileSync(file,html+'\n');
}
export function doc(l,r,title,body){write(l,r,`<h1 id="section-0">${title}</h1>\n${body}`);}
export const status=l=>p(l==='tc'?'目前公開配置為 MAGNE L1 與 M Hash L2 測試網。主網及正式結算尚未開放；部署狀態與網絡參數見 <a href="https://w3.magne.ai/network.html">官方網絡登記</a>。':'Public configurations currently cover MAGNE L1 and M Hash L2 testnets. Mainnet and production settlement are not open. See the <a href="https://w3.magne.ai/network.html">official network register</a> for deployment status and parameters.');
for(const l of ['en','tc']){
 const tc=l==='tc',t=(en,zh)=>tc?zh:en;
 doc(l,'/learning/what-is-magne',t('What is MAGNE.AI?','甚麼是 MAGNE.AI？'),p(t('MAGNE.AI combines mobile hardware, on-device AI and blockchain infrastructure. Its design connects user-controlled devices with applications and verifiable network records.','MAGNE.AI 結合行動硬件、端側 AI 與區塊鏈基礎設施，旨在連接由使用者控制的裝置、應用及可核對的網絡紀錄。'))+img('a999b92c4166-ma.png')+h('section-1',t('Roles in the system','系統中的角色'))+table([t('Layer','層級'),t('Role','角色')],[['MAG1',t('Device interaction, local computation and protected signing paths.','裝置操作、本機運算與受保護的簽署路徑。')],['MAGNE L1',t('Base-network design for identity, ownership and ecosystem coordination.','身份、所有權與生態協調的基礎網絡設計。')],['M Hash L2',t('EVM application execution, task receipts and contract events in the test environment.','測試環境中的 EVM 應用執行、任務回執及合約事件。')],['MHA',t('Magic Hash: the token whose allocation and release rules are set out in Tokenomics.','Magic Hash：分配與釋放規則見代幣經濟章節。')]])+h('section-2',t('Network security and device rewards','網絡安全與裝置獎勵'))+p(t('L1 consensus, L2 transaction ordering and device task rewards are separate mechanisms. The v1.1 GEN1 proposal measures availability and accepted work; buying or registering a phone does not itself grant validator or block-production rights. The L1 consensus specification and its relationship to validator staking require a versioned technical confirmation.','L1 共識、L2 交易排序與裝置任務獎勵屬不同機制。v1.1 GEN1 草案按可用性及有效任務計算獎勵；購買或登記手機本身不授予驗證者資格或出塊權。L1 共識規格及其與驗證者質押的關係，仍須以具版本的技術說明定稿。'))+h('section-3',t('Current stage','目前階段'))+status(l)+p(link(l,'/learning/tokenomics',t('Read allocation and GEN1 rules','閱讀分配及 GEN1 規則'))));
 doc(l,'/learning/pow',t('Proof of Work and device rewards','工作量證明與裝置獎勵'),h('section-1',t('What PoW means','PoW 的含義'))+p(t('Proof of Work (PoW) is a consensus approach in which participants perform computational work to compete for block production under the rules of a specific chain. Computational task completion, on its own, is not proof that a device participates in that consensus.','工作量證明（Proof of Work，PoW）是一類共識方式，參與者按特定鏈的規則進行運算競爭以取得出塊機會。完成運算任務本身，不代表裝置參與該鏈的共識。'))+h('section-2',t('How v1.1 uses the term mining','v1.1 中「挖礦」的範圍'))+p(t('GEN1 mining refers to the proposed distribution of the Mining Nodes allocation for eligible device availability and effective tasks. Its baseline, monthly budget, work checks and release schedule are defined in Tokenomics. It is not a per-phone block reward and does not imply that every device is a full node or validator.','GEN1 挖礦指按合資格裝置可用性與有效任務，擬從挖礦節點分配中發放獎勵。設備基準、月度預算、任務核驗及釋放表均見代幣經濟章節；這不是每台手機的出塊獎勵，也不表示每台裝置都是全節點或驗證者。'))+h('section-3',t('Consensus specification','共識規格'))+p(t('Earlier material mixed PoW, CometBFT and staking-based validator descriptions. This review draft does not treat those descriptions as one confirmed implementation. Publication of the final L1 consensus model requires the client version, validator-selection rules, finality conditions and security assumptions. L2 ordering and settlement must be specified separately.','早期材料混用了 PoW、CometBFT 與質押驗證者描述。本審核稿不將它們視為同一套已確認實作。L1 共識定稿須列明客戶端版本、驗證者選擇規則、最終確定條件與安全假設；L2 排序與結算機制另行說明。'))+p(link(l,'/networks/l1',t('L1 roles and technical status','L1 角色與技術狀態'))+' · '+link(l,'/learning/tokenomics#section-9',t('GEN1 release schedule','GEN1 釋放表'))));
 doc(l,'/learning/mha','Magic Hash (MHA)',p(t('Magic Hash (MHA) currently circulates as a token on BNB Smart Chain (BSC). The disclosed BSC contract identifies this current token; BSC transactions use BNB for network gas.','Magic Hash（簡稱 MHA）現階段以 BNB Smart Chain（BSC）上的代幣形式流轉。披露的 BSC 合約對應現行代幣；BSC 網絡交易以 BNB 支付 Gas。'))+img('2b5d720ea4b7-mha.png')+h('section-1',t('Planned network roles','規劃中的網絡用途'))+p(t('Within the MAGNE network design, MHA is proposed for gas, validator security staking and ecosystem incentives. Migration or integration with MAGNE L1 and M Hash L2 will require a separate announcement covering timing, supported networks, conversion rules and holder actions. Testnet gas tokens are separate from BSC MHA and do not establish migration entitlement.','在 MAGNE 自有網絡設計中，MHA 擬用於 Gas、驗證者安全質押及生態激勵。向 MAGNE L1 與 M Hash L2 遷移或整合的時間、網絡、轉換方式及持有人操作須另行公告。測試網 Gas 代幣與 BSC MHA 分開，不據此產生遷移權益。'))+h('section-2',t('Supply and release','供應與釋放'))+p(t('The allocation total remains 10,000,000,000 MHA. Release schedules describe distributions from the specified reserve pools, not new issuance above that total. Mining and validator allocations have their own schedules. Any future network fee-burning mechanism requires an explicit implementation specification; it is not a token-price commitment.','分配總量維持 10,000,000,000 MHA。釋放表描述指定儲備池的分配發放，不是超出該總量的新增發行。挖礦與驗證者分配各有釋放規則。未來網絡費用銷毀須有明確實作規格，不構成代幣價格承諾。'))+h('section-3',t('Governance design','治理設計'))+p(t('The design also references mBGT for reward coordination and protocol voting. Its retention, transferability and relationship to MHA voting rights remain design decisions to confirm; this does not announce issuance of another token.','設計稿亦提及 mBGT 用於獎勵協調及協議投票。是否保留、能否轉讓，以及與 MHA 投票權的關係仍待設計確認；此處不構成另一代幣的發行公告。'))+p(link(l,'/learning/tokenomics',t('Contract, reserve addresses and release rules','合約、儲備地址與釋放規則'))));
 doc(l,'/learning/incentives',t('Incentive Marketplace — design draft','激勵市場 · 設計草案'),p(t('This proposal describes how participating protocols could fund incentives for eligible reward vaults. It is separate from GEN1 device rewards and is not evidence of a live marketplace or L2 PoW mining. Activation requires confirmed contracts, eligible allocators and published vault rules.','本草案描述參與協議如何為合資格獎勵金庫提供激勵，與 GEN1 裝置獎勵分開。它不表示市場已啟用，也不將 L2 描述為 PoW 挖礦。啟用前須確認合約、具分配權的參與者及金庫規則。'))+h('section-1',t('Proposed flow','擬議流程'))+ul([t('A protocol deposits incentive tokens into an approved vault.','協議向獲批准金庫存入激勵代幣。'),t('An eligible allocator directs an authorised reward amount to the vault; the source allocation and spending authority must be documented.','合資格分配者將獲授權的獎勵額導向金庫；須披露來源分配及支出權限。'),t('Commission and participant awards are calculated from the funded incentive amount, subject to vault eligibility and available balance.','佣金與參與者獎勵按已提供的激勵額計算，受資格與可用餘額限制。')])+h('section-2',t('Roles','角色'))+table([t('Role','角色'),t('Responsibility','職責')],[[t('Protocol','協議'),t('Funds incentives and proposes vault terms.','提供激勵資金並提出金庫條款。')],[t('Reward allocator','獎勵分配者'),t('Exercises allocation authority under the final protocol rules; not automatically every miner or phone owner.','按最終協議規則行使分配權；不自動等同每位礦工或手機持有人。')],[t('Participant','參與者'),t('Provides eligible assets and claims awards under the vault rules.','提供合資格資產並按金庫規則領取獎勵。')]])+h('section-3',t('Draft vault controls','金庫控制草案'))+p(t('The earlier design proposed whitelisted vaults, up to two incentive tokens per vault, and governance approval for token or manager changes. Deposit withdrawal restrictions, rate-change rules, claim deadlines and any automated claims must be confirmed in the deployed contract terms before participation.','早期設計提出金庫白名單、每個金庫最多兩種激勵代幣，以及變更代幣或管理者須經治理批准。存款提取限制、費率變更、領取期限及自動領取功能，須在參與前以實際合約條款確認。'))+h('section-4',t('Funded coverage example','資金覆蓋算例'))+table([t('Scenario','情境'),t('Calculation','計算'),t('Coverage','覆蓋量')],[[t('Initial balance','初始餘額'),'2,000 USDC ÷ 10 USDC/MHA','200 MHA'],[t('New total balance of 2,500 USDC','更新後總餘額為 2,500 USDC'),'2,500 ÷ 11','227.27 MHA'],[t('Add 2,500 to an unspent 2,000','未使用的 2,000 再新增 2,500'),'(2,000 + 2,500) ÷ 11','409.09 MHA']])+p(t('Coverage is a rate-based illustration, not an MHA market-price forecast. Existing obligations must be deducted before calculating available coverage.','覆蓋量屬指定費率算例，不是 MHA 市場價格預測；計算可用覆蓋量前須扣除已有承諾。'))+h('section-5',t('Commission example','佣金算例'))+p(t('At 100 USDC per 10 MHA, directing 1 MHA corresponds to 10 USDC of incentives. At a 5% commission, the allocator receives 0.5 USDC and participants share 9.5 USDC. The earlier proposed default of 5% and maximum of 20% remain design parameters, not active rates.','每 10 MHA 對應 100 USDC 時，導入 1 MHA 對應 10 USDC 激勵。按 5% 佣金計，分配者取得 0.5 USDC，參與者分配 9.5 USDC。早期草案的預設 5%、最高 20% 仍屬設計參數，不是已啟用費率。'))+h('section-6',t('Release and claims','釋放與領取'))+p(t('A vault may propose a streaming or staged release schedule. A quoted rate, a funded balance and a claimable award are different quantities. The final contract must specify eligibility, release timing, rounding and expiry; this draft does not promise unlimited claim time.','金庫可提出串流或分期釋放。報價費率、已存入資金與可領取獎勵屬不同數值。最終合約須列明資格、釋放時間、捨入及到期規則；本草案不承諾無限期領取。')));
 doc(l,'/learning/metrics',t('Network metrics and measurement','網絡指標與測量'),status(l)+p(t('Metrics must identify the network, client/configuration version, observation period and workload. Earlier 1-second/2-second block times and 100M/140M gas limits were inconsistent; they are not presented here as verified current settings.','指標須指明網絡、客戶端／配置版本、觀測期間及工作負載。早期 1 秒／2 秒出塊、100M／140M Gas 上限的描述不一致，本頁不將其列為已核實的現行參數。'))+h('section-1',t('Gas model: illustrative parameters','Gas 模型：示例參數'))+table([t('Parameter','參數'),t('Illustration only','僅供算例')],[['Gas limit','100,000,000'],['Elasticity','2'],['Gas target','50,000,000'],['Change denominator','8']])+p(t('With this EIP-1559 example, usage at the 50M target leaves the base fee unchanged. A full 100M block permits an increase of approximately 12.5%, subject to integer rounding and the minimum increment. Actual chain settings must be read from the applicable implementation.','在此 EIP-1559 算例中，使用量等於 50M 目標時基本費不變；100M 滿區塊的基本費增幅約為 12.5%，受整數捨入及最小增量規則影響。實際網絡設定須以對應實作為準。'))+h('section-2',t('Throughput and fees','吞吐量與費用'))+p(t('At 100M gas per second, standard transfers using 21,000 gas have a theoretical full-block ceiling of about 4,761 transactions per second, before other overhead. This calculation is not a measured MAGNE benchmark. An 8,000+ TPS claim requires a different documented workload or gas budget.','在每秒 100M Gas 假設下，每筆消耗 21,000 Gas 的標準轉帳，滿區塊理論上限約為每秒 4,761 筆，尚未計其他開銷。此計算不是 MAGNE 實測結果；8,000+ TPS 須有不同且明確的工作負載或 Gas 預算支持。'))+p(t('Benchmark reports should include transaction mix, hardware, duration, accepted and failed transactions, confirmation latency and the corresponding block range. Dollar-denominated fees vary with gas usage, fee parameters and token price; no fixed dollar fee or undated competitor comparison is asserted here.','基準測試應列出交易類型、硬件、持續時間、成功與失敗交易、確認延遲及區塊範圍。美元費用隨 Gas 用量、費率與代幣價格改變；本頁不保證固定美元費用，也不使用無日期的競品比較。'))+h('section-3',t('Confirmation, finality and withdrawals','確認、最終確定性與提款'))+table([t('Measure','指標'),t('Meaning','含義')],[[t('L2 inclusion','L2 納入'),t('A transaction appears in an L2 block; this alone is not settlement finality.','交易被納入 L2 區塊，本身不等於結算最終確定。')],[t('L1 settlement finality','L1 結算最終確定'),t('Depends on L1 consensus and the deployed settlement protocol.','取決於 L1 共識及已部署的結算協議。')],[t('Withdrawal period','提款期間'),t('Includes the applicable bridge/challenge process; a 7-day example is not a universal confirmation time.','包括適用橋接／挑戰流程；7 天示例不是通用交易確認時間。')]])+p('<a href="https://eips.ethereum.org/EIPS/eip-1559">EIP-1559</a> · '+link(l,'/networks/faucet',t('Fee components','費用組成'))));
 doc(l,'/networks/faucet',t('Gas and fees','Gas 與費用'),p(t('Gas measures execution work. A transaction fee is not the same as its gas limit or the quoted gas price.','Gas 衡量執行工作量。交易費用、Gas 上限與 Gas 價格是不同概念。'))+h('section-1',t('Fee components','費用組成'))+p(t('In the proposed L2 design, the fee includes execution gas plus the applicable cost of publishing data to L1. The data component must be estimated through the deployed fee mechanism; it is not obtained by reusing the L2 execution gas quantity. Any additional fee component must be disclosed with its implementation version.','在擬議 L2 設計中，費用包括執行 Gas 及向 L1 發布資料的適用成本。資料費應透過已部署的費用機制估算，不能直接套用 L2 執行 Gas 用量；其他費用組成須隨實作版本披露。'))+code('L2 total fee = execution gas used × effective gas price + applicable L1 data fee')+h('section-2',t('Base fee example','基本費算例'))+p(t('For an EIP-1559 block limit of 100M, elasticity of 2 and denominator of 8, the target is 50M gas. At the target the base fee remains unchanged; a full block produces approximately a 12.5% increase. These are illustrative values, not confirmed live settings.','若 EIP-1559 區塊上限為 100M、彈性倍數 2、分母 8，目標為 50M Gas。達到目標時基本費不變，滿區塊時增幅約為 12.5%。這些是算例參數，不是已確認的即時配置。'))+h('section-3',t('Before submitting a transaction','提交交易前'))+ul([t('Confirm the network and request an estimate from its RPC and wallet.','確認網絡，透過其 RPC 及錢包取得費用估算。'),t('BSC MHA transfers require BNB gas; MAGNE testnets use their own test gas assets.','BSC 上的 MHA 轉帳需要 BNB Gas；MAGNE 測試網使用各自測試 Gas 資產。'),t('Batching and compression can reduce per-transaction data costs. ZK proofs are not asserted here as an enabled MAGNE fee-reduction mechanism.','批次與壓縮可降低單筆資料成本。本頁不將 ZK 證明列作 MAGNE 已啟用的降費機制。')])+p(link(l,'/learning/metrics',t('Measurement assumptions','測量假設'))+' · <a href="https://eips.ethereum.org/EIPS/eip-1559">EIP-1559</a>'));
 for(const layer of [1,2])doc(l,`/networks/l${layer}`,layer===1?t('MAGNE Layer 1','MAGNE Layer1'):t('M Hash Layer 2','M Hash Layer2'),status(l)+img(layer===1?'db4ba7abcd9a-m-l1.png':'6d14d021aeed-m-l2.png')+h('section-1',t('Architecture and responsibilities','架構與職責'))+p(layer===1?t('MAGNE L1 is the base-network design for identity, ownership and ecosystem coordination. EVM execution and network consensus have different responsibilities: execution updates application state, while consensus determines agreement on the accepted chain. The final consensus, validator selection and finality specification remain subject to technical confirmation.','MAGNE L1 是身份、所有權及生態協調的基礎網絡設計。EVM 執行與網絡共識職責不同：執行更新應用狀態，共識決定節點如何就接受的鏈達成一致。最終共識、驗證者選擇及最終確定規格仍待技術確認。'):t('M Hash L2 uses an OP Stack-oriented design to execute applications and record task receipts. Execution, ordering, derivation, data publication and settlement are separate responsibilities. Asynchronous batch submission does not remove the need for consensus or settlement security on L1.','M Hash L2 採用面向 OP Stack 的設計，執行應用並記錄任務回執。執行、排序、推導、資料發布及結算各有職責；非同步批次提交不代表移除 L1 的共識或結算安全要求。'))+h('section-2',t('Components and release requirements','組件與發布要求'))+(layer===1?ul([t('Publish the client release and network configuration.','公布客戶端版本及網絡配置。'),t('Specify validator admission, permissions, failure recovery and finality assumptions.','列明驗證者准入、權限、故障恢復及最終確定假設。'),t('Keep device task rewards and validator security rewards in their respective allocation rules.','裝置任務獎勵與驗證者安全獎勵各按所屬分配規則處理。')]):table([t('Responsibility','職責'),t('Typical OP Stack component','典型 OP Stack 組件')],[[t('EVM execution','EVM 執行'),'op-geth'],[t('Rollup derivation and sequencing integration','Rollup 推導及排序整合'),'op-node'],[t('Publish transaction batches to L1','向 L1 發布交易批次'),'batcher'],[t('State proposals and challenge monitoring','狀態提議與挑戰監察'),t('Proposer / challenger as applicable to the deployed fault-proof version','按所部署故障證明版本採用 proposer／challenger')]]))+p(t('This is a role map, not a complete deployment inventory. Production disclosure must identify addresses, permissions, data availability, proof/verification configuration and recovery procedures.','此處是角色說明，不是完整部署清單。正式發布須列明地址、權限、資料可用性、證明／驗證配置及恢復流程。'))+h('section-3',t('Token and participation rules','代幣與參與規則'))+p(link(l,'/learning/tokenomics',t('Tokenomics defines reserve release and GEN1 rewards.','代幣經濟章節定義儲備釋放及 GEN1 獎勵。'))+' '+t('Annual reserve schedules do not create automatic new issuance. A phone joining the task network does not thereby become a consensus validator.','儲備年度釋放表不產生自動增發；手機加入任務網絡不因此成為共識驗證者。'))+p(link(l,'/developers/net-config',t('Testnet configuration','測試網配置'))));
 doc(l,'/solutions/get-mha',t('Get and identify MHA','取得與識別 MHA'),h('section-1',t('Current BSC token','現行 BSC 代幣'))+p(t('The full name is Magic Hash and the symbol is MHA. Verify the network and contract before obtaining or transferring tokens; a matching name or logo is insufficient.','代幣全名為 Magic Hash，符號為 MHA。取得或轉帳前須核對網絡與合約；僅名稱或圖示相同不足以識別。'))+code('BNB Smart Chain · Chain ID 56\n0x37c563cdf4606d4302abb395cdb94e79d31233ed')+p('<a href="https://bscscan.com/token/0x37c563cdf4606d4302abb395cdb94e79d31233ed">BscScan</a> · '+link(l,'/learning/tokenomics#token-contract',t('Contract register','合約登記')))+p(t('For supported trading venues, use the official listing notices and the venue’s current deposit/withdrawal page. Check the supported BSC network and service status before transferring. This guide does not promise a trading price or liquidity.','支援交易渠道以官方上市公告及交易平台當前充提頁面為準。轉帳前核對是否支援 BSC 及當前服務狀態；本指引不承諾交易價格或流動性。'))+h('section-2',t('Testnet gas assets','測試網 Gas 資產'))+p(t('For contract and application development, use the relevant testnet faucet and a test wallet. Test assets have no stated mainnet value and are not the BSC MHA token. Never send real assets to a testnet address expecting a bridge or conversion.','開發合約與應用時，使用對應測試網水龍頭及測試錢包。測試資產不具有已公布的主網價值，也不是 BSC MHA；不要把向測試網地址發送真實資產當作橋接或兌換。'))+p('<a href="https://faucet.testnet.magicalhash.com">Testnet faucet</a> · '+link(l,'/developers/net-config',t('Network configuration','網絡設定')))+h('section-3',t('Future migration','未來遷移'))+p(t('Migration to MAGNE-owned networks requires a separate official announcement. There is no migration action to perform from this whitepaper page.','向 MAGNE 自有網絡遷移須另行發布正式公告；本白皮書頁面沒有要求持有人現在執行遷移操作。')));
 doc(l,'/solutions/why-l2',t('Why MAGNE needs Layer 2','為何 MAGNE 需要 Layer2'),h('section-1',t('Separate execution workloads','分擔執行工作負載'))+p(t('High-frequency applications can compete for limited L1 block space. The L2 design moves application execution and batching to a separate layer while retaining an explicit settlement relationship with L1. This is an architectural objective, not evidence of current production transaction volume.','高頻應用可能競爭有限的 L1 區塊空間。L2 設計將應用執行與批次處理分到另一層，並保留明確的 L1 結算關係。這是架構目標，不代表當前正式網絡交易量。'))+h('section-2',t('Benefits and dependencies','效益與依賴'))+ul([t('Batching can share publication costs across transactions.','批次可讓多筆交易分攤發布成本。'),t('EVM compatibility supports familiar contract tools; it does not guarantee every application works unchanged.','EVM 相容性支援既有合約工具，但不保證每個應用毋須調整即可運作。'),t('Security depends on data availability, settlement verification, sequencing permissions and upgrade controls.','安全性依賴資料可用性、結算驗證、排序權限與升級控制。'),t('A bridge must be explicitly deployed, audited and enabled before assets can move through it.','資產橋接須先有明確部署、審查及啟用的橋接系統。')])+h('section-3',t('Status and measurements','狀態與測量'))+status(l)+p(link(l,'/learning/metrics',t('Metrics and assumptions','指標與假設'))));
}
console.log('Reconciled core architecture, token scope, incentives, metrics and MHA guide.');
